from collections import Counter
from math import comb

def p_count(t, z):
    if abs(z)>t or (t+z)%2:
        return 0
    return comb(t, (t+z)//2)

def image_count(t,l,r,a,z):
    L=r-l
    # The generous finite window includes every nonzero image.
    return sum(p_count(t,z-a+2*k*L)-p_count(t,z+a-2*l+2*k*L) for k in range(-t-10,t+11))

killed_checks=0
for l in range(-3,2):
    for L in range(1,10):
        r=l+L
        for a in range(l,r+1):
            dist=Counter({a:1}) if l<a<r else Counter()
            for t in range(41):
                for z in range(l,r+1):
                    assert image_count(t,l,r,a,z)==dist[z], (t,l,r,a,z)
                    killed_checks+=1
                new=Counter()
                for z,n in dist.items():
                    for y in [z-1,z+1]:
                        if l<y<r:
                            new[y]+=n
                dist=new

range_checks=0
reflection_checks=0
for a in [0,2]:
    triples=Counter({(a,a,a):1})
    for t in range(41):
        if a==0:
            assert sum(n for (m,M,z),n in triples.items() if M<2)==sum(p_count(t,j) for j in range(-2,2))
            reflection_checks+=1
        for (m,M,z),count in triples.items():
            if m<=0 and M>=2:
                actual=image_count(t,m-1,M+1,a,z)-image_count(t,m,M+1,a,z)-image_count(t,m-1,M,a,z)+image_count(t,m,M,a,z)
                assert actual==count,(t,a,m,M,z)
                range_checks+=1
        new=Counter()
        for (m,M,z),count in triples.items():
            for y in [z-1,z+1]:
                new[min(m,y),max(M,y),y]+=count
        triples=new
print({'killed_image_exact_checks':killed_checks,'common_range_exact_checks':range_checks,'reflection_exact_checks':reflection_checks,'time_range':'0..40','result':'No counterexample; finite checks do not prove uniform claims.'})
