from collections import Counter

checks=0
states=0
tv=[]
end_laws={}
for a in [0,2]:
    actual=Counter({(frozenset(),a):1})
    triples=Counter({(a,a,a):1})
    for t in range(1,7):
        next_actual=Counter()
        for (lamps,z),count in actual.items():
            for departure_bit in [0,1]:
                departure=lamps|{z} if departure_bit else lamps-{z}
                for y in [z-1,z+1]:
                    for arrival_bit in [0,1]:
                        final=departure|{y} if arrival_bit else departure-{y}
                        next_actual[frozenset(final),y]+=count
        actual=next_actual
        next_triples=Counter()
        for (m,M,z),count in triples.items():
            for y in [z-1,z+1]:
                next_triples[min(m,y),max(M,y),y]+=count
        triples=next_triples
        mixture=Counter()
        for (m,M,z),count in triples.items():
            width=M-m+1
            for mask in range(1<<width):
                lamps=frozenset(m+i for i in range(width) if mask&(1<<i))
                mixture[lamps,z]+=count*(1<<(2*t-width))
        assert actual==mixture,(a,t)
        assert sum(actual.values())==8**t
        checks+=1
        states+=len(actual)
        end_laws[a,t]=actual
